CREATE DATABASE IF NOT EXISTS motocontrol CHARACTER SET utf8mb4;
USE motocontrol;
CREATE TABLE IF NOT EXISTS clientes (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, telefono VARCHAR(20) NOT NULL, correo VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS motocicletas (id INT AUTO_INCREMENT PRIMARY KEY, id_cliente INT NOT NULL, placa VARCHAR(10) NOT NULL UNIQUE, marca VARCHAR(40) NOT NULL, modelo VARCHAR(40) NOT NULL, kilometraje INT NOT NULL DEFAULT 0, FOREIGN KEY (id_cliente) REFERENCES clientes(id));
CREATE TABLE IF NOT EXISTS repuestos (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(100) NOT NULL, cantidad INT NOT NULL, precio DECIMAL(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS ordenes (id INT AUTO_INCREMENT PRIMARY KEY, id_moto INT NOT NULL, descripcion VARCHAR(255) NOT NULL, fecha DATE NOT NULL, mecanico VARCHAR(80) NOT NULL, estado VARCHAR(20) NOT NULL DEFAULT 'Pendiente', FOREIGN KEY (id_moto) REFERENCES motocicletas(id));
CREATE TABLE IF NOT EXISTS trabajos (id INT AUTO_INCREMENT PRIMARY KEY, id_orden INT NOT NULL, descripcion VARCHAR(255) NOT NULL, fecha DATE NOT NULL, kilometraje INT NOT NULL, FOREIGN KEY (id_orden) REFERENCES ordenes(id));
CREATE TABLE IF NOT EXISTS recordatorios (id INT AUTO_INCREMENT PRIMARY KEY, id_moto INT NOT NULL, descripcion VARCHAR(255) NOT NULL, fecha DATE NOT NULL, km_objetivo INT NOT NULL, FOREIGN KEY (id_moto) REFERENCES motocicletas(id));
